int probe_usb_interface(struct usb_interface *intf, const struct usb_device_id *id) {
    struct can_device *host_config = NULL;
    struct can_device *device_config = NULL;
    int ret = -ENOMEM;

    host_config = kmalloc(sizeof(*host_config), GFP_KERNEL);
    if (!host_config)
        goto error;

    device_config = kmalloc(sizeof(*device_config), GFP_KERNEL);
    if (!device_config)
        goto error;

    ret = usb_control_msg(intf->cur_altsetting->desc.bInterfaceNumber,
                          USB_DIR_OUT | USB_TYPE_CLASS | USB_RECIP_INTERFACE,
                          0x01, 0x00, intf->cur_altsetting->desc.bInterfaceNumber,
                          NULL, 0, USB_CTRL_GET_TIMEOUT);
    if (ret < 0)
        goto error;

    if (intf->num_altsetting > MAX_INTERFACES) {
        ret = -EINVAL;
        goto error;
    }

    host_config->can_id = intf->cur_altsetting->desc.bInterfaceNumber;
    device_config->can_id = intf->cur_altsetting->desc.bInterfaceNumber;

    return 0;

error:
    kfree(host_config);
    kfree(device_config);
    return ret;
}

int usb_init_device(struct usb_interface *intf, const struct usb_device_id *id) {
    struct host_config *host_cfg = NULL;
    struct device_config *dev_cfg = NULL;
    int ret = -ENOMEM;

    host_cfg = kmalloc(sizeof(*host_cfg), GFP_KERNEL);
    if (!host_cfg)
        goto err_out;

    dev_cfg = kmalloc(sizeof(*dev_cfg), GFP_KERNEL);
    if (!dev_cfg)
        goto err_host_cfg;

    ret = usb_control_msg(usb_get_dev(intf->usb_dev),
                          usb_sndctrlpipe(intf->usb_dev, 0),
                          HOST_CONFIG_REQ,
                          USB_TYPE_CLASS | USB_RECIP_INTERFACE,
                          0, 0, host_cfg, sizeof(*host_cfg), USB_CTRL_MSG_TIMEOUT);
    if (ret < 0)
        goto err_dev_cfg;

    ret = usb_get_config_descriptor(intf->usb_dev, dev_cfg);
    if (ret < 0)
        goto err_dev_cfg;

    if (dev_cfg->num_interfaces > MAX_INTERFACES) {
        ret = -EINVAL;
        goto err_dev_cfg;
    }

    dev_cfg->can_dev = alloc_can_dev();
    if (!dev_cfg->can_dev) {
        ret = -ENOMEM;
        goto err_dev_cfg;
    }

    can_dev_init(dev_cfg->can_dev);

    return 0;

err_dev_cfg:
    kfree(dev_cfg);
err_host_cfg:
    kfree(host_cfg);
err_out:
    return ret;
}

int usb_init_device(struct usb_interface *intf, const struct usb_device_id *id) {
    struct host_config *host_config;
    struct device_config *device_config;
    struct device *device;
    int ret;

    host_config = kmalloc(sizeof(*host_config), GFP_KERNEL);
    if (!host_config)
        return -ENOMEM;

    device_config = kmalloc(sizeof(*device_config), GFP_KERNEL);
    if (!device_config) {
        kfree(host_config);
        return -ENOMEM;
    }

    ret = usb_control_msg(intf->cur_altsetting->desc.bInterfaceNumber,
                          host_config, USB_DIR_OUT | USB_TYPE_CLASS,
                          0, 0, NULL, 0, USB_CTRL_MSG_TIMEOUT);
    if (ret < 0) {
        kfree(device_config);
        kfree(host_config);
        return ret;
    }

    ret = usb_get_device_config(intf->cur_altsetting->desc.bNumInterfaces,
                                device_config);
    if (ret < 0) {
        kfree(device_config);
        kfree(host_config);
        return ret;
    }

    if (device_config->num_interfaces > MAX_INTERFACES) {
        kfree(device_config);
        kfree(host_config);
        return -EINVAL;
    }

    device = kmalloc(sizeof(*device), GFP_KERNEL);
    if (!device) {
        kfree(device_config);
        kfree(host_config);
        return -ENOMEM;
    }

    device_init(device, host_config, device_config);

    create_can_device_instances(device);

    return 0;
}

int usb_probe_interface(struct usb_interface *intf, const struct usb_device_id *id) {
    struct can_device_config *host_config = NULL;
    struct can_device_config *device_config = NULL;
    struct can_device *can_dev = NULL;
    int ret = -ENOMEM;

    host_config = kmalloc(sizeof(*host_config), GFP_KERNEL);
    if (!host_config)
        goto out;

    device_config = kmalloc(sizeof(*device_config), GFP_KERNEL);
    if (!device_config)
        goto out_free_host;

    ret = usb_control_msg(intf->cur_altsetting->desc.bInterfaceNumber,
                          USB_DIR_OUT | USB_TYPE_CLASS | USB_RECIP_INTERFACE,
                          USB_REQ_SET_CONFIGURATION, 0, 0,
                          host_config, sizeof(*host_config), USB_CTRL_MSG_TIMEOUT);
    if (ret < 0)
        goto out_free_device;

    ret = usb_get_device_config_descriptor(intf->cur_altsetting->desc.bInterfaceNumber, device_config);
    if (ret < 0)
        goto out_free_device;

    if (device_config->num_interfaces > MAX_USB_INTERFACES) {
        ret = -EINVAL;
        goto out_free_device;
    }

    can_dev = can_device_alloc();
    if (!can_dev)
        goto out_free_device;

    can_dev_init(can_dev, host_config, device_config);
    can_dev_register(can_dev);

    return 0;

out_free_device:
    kfree(device_config);
out_free_host:
    kfree(host_config);
out:
    return ret;
}
